				normal_strength: Type.Optional(Type.Number()),
				roughness: Type.Optional(Type.Tuple([Type.Number(), Type.Number()])),
				notes: Type.Optional(Type.String({ description: "What it's for" })),
			}),
			async execute(_id, params, signal, onUpdate) {
